local PACKING_BASE = 4096
local function get(spellID, professionID)
    local packed = ranges and ranges[spellID]
    if type(packed) == "table" then packed = packed[professionID] end
    if not packed then return end
    local yellow, gray = math.floor(packed / PACKING_BASE), packed % PACKING_BASE
    return yellow, math.floor((yellow + gray) / 2), gray, minimumRanks[spellID]
end

FC.SkillRanges = {Get = get}
